def _nucmer_hits_to_percent_identity(nucmer_hits):
        """Input is hits made by self._parse_nucmer_coords_file.
           Returns dictionary. key = contig name. Value = percent identity of hits to that contig"""
           percent_identity_dict = {}
           for hit in nucmer_hits:
               contig_name = hit[0]
               if contig_name not in percent_identity_dict:
                   percent_identity_dict[contig_name] = []
               percent_identity_dict[contig_name].append(hit[1])
           for contig_name in percent_identity_dict:
               percent_identity_dict[contig_name] = sum(percent_identity_dict[contig_name])/len(percent_identity_dict[contig_name])
           return percent_identity_dict

